import React, { useEffect, useState } from "react";



import { getStore, updStore, gen16CodeId, compareJSON, fetchEncryptStream, qryStore, AccountYears } from "../../../stores/Utils";

import { CheckBoxSlide_Cmpt, TextInput_Cmpt, CheckBox_Cmpt, SvgIcon_Cmpt } from "../../../components";


import "./styles.css"
import { CloseModal, OpenModal } from "../../../components/DialogHRM";
import SaveAlert from "./saveAlert";
import { SelectDropAccount_Cmpt } from "../../ComprobanteParametrizados";
import DeleteAlert from "../../Inventory/component/deleteAlert";

const TextInput = TextInput_Cmpt();

const DropInput = SelectDropAccount_Cmpt();

const CheckBox = CheckBox_Cmpt();
const Svg = SvgIcon_Cmpt();

const frmNm = "upd_comprobantebyId"

const UpdComprobante  = ({data, confirm, item}) => {
	const [initialize, setInitialize] = useState(false);
	const [obs, set_obs] = useState(0);
	useEffect(() => {
		if (!initialize) {
			setInitialize(true);
			
			set_obs(gen16CodeId())
		}
	});

	const updFrm = (f, v, k) => {
		let frm2 = getStore(frmNm) || {};
		if(k){
			if( !frm2[k]){
				frm2[k] = {};
			}
			frm2[k][f] = v;
		}else{
			frm2[f] = v;
		}
		updStore(frmNm, frm2);
		
		set_obs(gen16CodeId())
	};




		
	
	const copy  = async ()  => {
		

		let frm2Upd = {...getStore("comprobante_list")[item.operationId]}
		frm2Upd.operationId = gen16CodeId();
		let bdyq2 = {...getStore(qryStore())?.add_opera};
		bdyq2.params = {
			businessId:  getStore("profileUser")?.businessId,
			year:getStore("date_current_year"),
		}
		bdyq2.form=frm2Upd;
		const res = fetchEncryptStream(bdyq2);
		const td = await res;
		if (td) {
			updStore(frmNm, {});
			updStore(frmNm + "_bck", {});
			confirm && confirm();
			data?.modalID && CloseModal({id:data?.modalID})
		}
		
	
};


	const save  = async ()  => {
		
			// revision
			let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck"));
			
			let bdyq2 = {...getStore(qryStore())?.upd_opera};
			bdyq2.params = {
				businessId:  getStore("profileUser")?.businessId,
				operationId: item["operationId"],
				year:getStore("date_current_year"),
			}
			bdyq2.data2update=diff.data;
			
			const res = fetchEncryptStream(bdyq2);
			const td = await res;
			if (td) {
				updStore(frmNm, {});
				updStore(frmNm + "_bck", {});
				confirm && confirm();
				data?.modalID && CloseModal({id:data?.modalID})
			}
		
	};



	let flds = ["document","amount","type","description", "account", "subAccount", "comprobanteId"]

	let diff = compareJSON(flds,getStore(frmNm),getStore(frmNm + "_bck") )




	
	
	const OpenSaveAlert =  (func) => {

		if(getStore("profileUser")?.isAdmin){
			func()

		}else{ 
			if(!getStore("profileUser")?.isAdmin && AccountYears()[getStore("date_current_year")]?.isClosed){
				let modaldata = {};
				modaldata["zIndex"] = 450;
				modaldata["height"] = "40vh";
				// data['observeResize']=true;
				modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
				let titleCm = <div className="_dsplFlx ">
					<div className="centerBx">
						<Svg 
							name={"alert"} 
							color={"var(--hrm_palette-selected-nav-text)"}
						/>
					</div>
					<h4 className="" style={{padding: 4, margin: 0}}>
						{"No puede actualizar este registro!!!"}
					</h4>
				</div>
				
				modaldata["content"] = <DeleteAlert
					label={titleCm} 
					labelColor={"var(--hrm_palette-selected-nav-text)"} 
					body={"El año contable al que pertenece esta cerrado"} 
					btnConfirm={"OK"}
					
				/>
				OpenModal(modaldata);
			}
			else{

				let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
				if(Date.now() > lastTimeCallModal){
					updStore("lastTimeCallModal", Date.now()+320);
					
					let modaldata = {};
					modaldata["zIndex"] = 450;
					modaldata["height"] = "40vh";
					// data['observeResize']=true;
					modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
					modaldata["content"] = <SaveAlert confirm={func} item={item} />
					OpenModal(modaldata);
				}
			}
		}
	}

	const handlePick = (acc,subacc) => {
		updFrm("account",acc);
		updFrm("subAccount",subacc?subacc:"")
	}
	


	
	const deleteComprobante = async () => {
		if(AccountYears()[getStore("date_current_year")]?.isClosed){
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <DeleteAlert
				label={"No puede eliminar este registro !!!"} 
				labelColor={"var(--hrm_palette-selected-nav-text)"} 
				body={"El año contable al que pertenece esta cerrado"} 
				btnConfirm={"OK"}
				
			/>
			OpenModal(modaldata);
		}
		else{
			let bdyq2 = {...getStore(qryStore())?.delete_opera};
			bdyq2.params = {
				businessId:  getStore("profileUser")?.businessId,
				operationId:  item["operationId"],
				year:getStore("date_current_year"),
			}
			const res = fetchEncryptStream(bdyq2);
			const td = await res;
			if (td) {
				updStore(frmNm, {});
				updStore(frmNm + "_bck", {});
				confirm && confirm();
				data?.modalID && CloseModal({id:data?.modalID})
			}
		}
	}
	

	const OpenDeleteAlert =  () => {
		let lastTimeCallModal = getStore("lastTimeCallModal") || 0;
		if(Date.now() > lastTimeCallModal){
			updStore("lastTimeCallModal", Date.now()+320);
			
			let modaldata = {};
			modaldata["zIndex"] = 450;
			modaldata["height"] = "40vh";
			// data['observeResize']=true;
			modaldata["props"] = { minHeight: "1vh", overlay: true, closeEvent: ()=>{}  };
			modaldata["content"] = <SaveAlert confirm={deleteComprobante} item={item} />
			OpenModal(modaldata);
		}
	}

	
	return (
		<div
		style={{
			maxHeight: "80vh",
			width: "560px",
			overflow: "auto",
			background: "var(--hrm_palette-general-background-b)",
			borderRadius: 13,
			padding: "10px 19px"
		}}
		>
			<div className="_dsplFlx ">
				<p className="form_title">
					Actualizar Operacion 
				</p>
				<div className="flexSpace"/>
				<div className="icon" style={{marginLeft:19}} onClick={()=>OpenSaveAlert(copy)}>
					<Svg 
						name={"content-copy"} 
						color={"var(--hrm_palette-blue-purple)"}
					/>
				</div>
				<div className="icon" style={{marginLeft:19}} onClick={OpenDeleteAlert}>
					<Svg 
						name={"outline_delete"} 
						color={"#c62828"}
					/>
				</div>
			</div>

			<div className="_dsplFlx ">
				<TextInput  
					init={getStore(frmNm)?.["document"]} 
					label={"Documento"} 
					width={120} 
					updChanges={(e)=>updFrm("document",e)}
				/>
				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.["amount"]} 
					label={"Importe"} 
					width={120} 
					type={"number"}
					updChanges={(e)=>updFrm("amount",e)}
				/>
				<div className="flexSpace"/>
				<TextInput  
					init={getStore(frmNm)?.["comprobanteId"]} 
					label={"comprobanteId"} 
					width={120} 
					updChanges={(e)=>updFrm("comprobanteId",e)}
				/>
			</div>
			
			<TextInput  
				init={getStore(frmNm)?.["description"]} 
				label={"Descripcion"} 
				width={520} 
				updChanges={(e)=>updFrm("description",e)}
			/>

				<div style={{margin: "30px 0 0 18px"}}/>
				
			
			{getStore(frmNm)?.account?
			<div className=" acc_dtls">			
					<div className="_dsplFlx"  >
						<div className="code" style={{color: "#646cff"}} onClick={()=>updFrm("account",null)}>
							{getStore("account_ids")?.[getStore(frmNm)?.account]?.code || "escoja uno"} 
						</div>
						<div className="name">
						{getStore("account_ids")?.[getStore(frmNm)?.account]?.name}
						</div>
					</div>
					<div className="flexSpace"/>
					{getStore(frmNm)?.subAccount ?
					<div className="_dsplFlx"  style={{margin: "10px 0 0 18px"}}>
						<div className="code" >
							{getStore("sub_account_ids")?.[getStore(frmNm)?.subAccount]?.subAccount} 
						</div>
						<div className="name">
						{getStore("sub_account_ids")?.[getStore(frmNm)?.subAccount]?.subAccountName} 
						</div>
					</div>
					:null}
				</div>
				:
				<DropInput
					width={420}
					handleClick={handlePick}
				/>}
			<div className="_dsplFlx " style={{padding: "18px"}}>
					<div className="flexSpace"/>
					<CheckBox 
						data={[
							{label: "Deudoras", id:"debit"},
							{label: "Acredoras", id:"credit"}
							
						]}
						active={getStore(frmNm)?.["type"]}
						updSelect={(e)=>updFrm("type",e)}
					/>
					<div className="flexSpace"/>
				</div>
			<div style={{margin: "70px 0 0 18px"}}>
				
			</div>
			
			<div className="_dsplFlx ">
				<div className="flexSpace"/>
				{diff?.hasChange ?
				<div className="card">
					<button onClick={()=>OpenSaveAlert(save)}>
						Actualizar
					</button>
				</div>
				:null}
			</div>
		

			
		</div>
	);
};

export default UpdComprobante;
